using CairoMakie

using AttractorsQGP


"""
    looking_for_plateu(D, N)


procedure created for using the all type of lpca combination
"""
function looking_for_plateu(D, N)
    CairoMakie.activate!()

    K = [30, 71, 86]
    KNN(N, D) = D / 2 * (N^(1 / 2) / D^(1 / 2))
    taus = [0.2, 0.4, 0.8, 2]
    figures_mis = Dict(); figures_hjsw = Dict()
    mis = load_dataset("datasets/hjsw_lpca/mis_matched_seed5.h5")
    hjsw = load_dataset("datasets/hjsw_lpca/hjsw_matched_seed5.h5")
    for i in K
        for j in taus
            figures_mis[(i, j)] = marchenko(mis, D = 2, K_sweep = [6:2:150...], K = i, tau = j)
            figures_hjsw[(i, j)] = marchenko(hjsw, D = 3, K_sweep = [6:2:150...], K = i, tau = j)
        end
    end
    for ((i, j), result) in figures_hjsw
        filename = "publication_lpca/plateu/HJSWdpr_K_$(i)_tau_$(j).pdf"
        save(filename, result.fig)
        println("Zapisano: $filename")
    end
    for ((i, j), result) in figures_mis
        filename = "publication_lpca/plateu/MISdpr_K_$(i)_tau_$(j).pdf"
        save(filename, result.fig)
        println("Zapisano: $filename")
    end
    return
end
